#include <compare>
#include <cstdint>
#include <ostream>
#include <stdexcept>
#include <string>
#include <utility>

class Money {
public:
    Money(std::int64_t cents, std::string currency)
        : cents_(cents), currency_(std::move(currency)) {}

    bool operator==(const Money&) const = default;    // compares cents_ AND currency_.

    Money& operator+=(const Money& o) {               // modifies left operand.
        if (currency_ != o.currency_) throw std::invalid_argument("currency mismatch");
        cents_ += o.cents_;
        return *this;
    }
    friend Money operator+(Money a, const Money& b) {  // copy a, add, return new value.
        a += b;
        return a;
    }
    friend std::ostream& operator<<(std::ostream& os, const Money& m) {
        return os << m.cents_ / 100 << '.' << (m.cents_ % 100 < 10 ? "0" : "")
                  << m.cents_ % 100 << ' ' << m.currency_;   // non-negative amounts.
    }
private:
    std::int64_t cents_;
    std::string currency_;
};
```

| Operator | Convention |
|---|---|
| `==`. | const, all value-significant members. |
| `+`. | returns new value; operands unchanged. |
| `+=`. | modifies left, returns `*this` by reference. |
| `<<` for output. | non-member, returns the stream. |

